import{_ as e,o as n,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Solución de problemas","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/troubleshooting.md","filePath":"es-ES/user-guide/troubleshooting.md","lastUpdated":1785993908000}'),i={name:"es-ES/user-guide/troubleshooting.md"};function s(t,a,l,c,d,u){return n(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to &quot;Solución de problemas&quot;">​</a></h1><h2 id="el-atajo-global-no-responde" tabindex="-1">El atajo global no responde <a class="header-anchor" href="#el-atajo-global-no-responde" aria-label="Permalink to &quot;El atajo global no responde&quot;">​</a></h2><ol><li>Comprueba <strong>Configuración → Estado del Servicio</strong> — si el servicio en segundo plano no está en ejecución, reinstalarlo o reiniciarlo desde esa página suele solucionar problemas relacionados con la indexación, pero el propio atajo de mostrar/ocultar lo gestiona el proceso de la App, no el servicio, así que esto es una comprobación secundaria.</li><li>Si la aplicación en primer plano se ejecuta elevada (como administrador) y Lertaro no, Windows impide que los procesos con menos privilegios le envíen entradas. El proceso de escucha de atajos en segundo plano de Lertaro se eleva automáticamente siempre que tu cuenta sea administradora — sin ningún ajuste que activar, sin ningún aviso de UAC. Si los atajos siguen sin llegar a una ventana elevada, comprueba <strong><a href="./settings/service-status.html">Configuración → Estado del Servicio</a></strong> para confirmar que el servicio en segundo plano está en ejecución, ya que es lo que lanza el proceso de escucha elevado. Si tu cuenta no es administradora, no hay ninguna solución alternativa — Windows no permite que un proceso con menos privilegios envíe señales a uno con más privilegios.</li><li>Comprueba la <strong><a href="./settings/hotkeys-page.html#process-blacklist">Lista negra de procesos</a></strong> — si el nombre del ejecutable de la aplicación en primer plano se añadió ahí (a propósito o por accidente), los atajos globales de Lertaro se dejan pasar deliberadamente sin intervenir mientras esa aplicación tenga el foco.</li><li>Si la aplicación en primer plano es realmente de pantalla completa (ocupa todo el monitor), Lertaro también deja pasar automáticamente sus atajos por defecto — así no compite con juegos a pantalla completa. Si tu combinación configurada no va a chocar con nada que use la propia aplicación a pantalla completa, activa <strong>Seguir respondiendo mientras una app a pantalla completa tiene el foco</strong>, junto a <strong>Configuración → Atajos → Mostrar/Ocultar búsqueda rápida</strong>, para que también funcione ahí. En caso contrario, cambiar de aplicación con alt-tab, o ejecutar la aplicación en modo ventana sin bordes en lugar de pantalla completa exclusiva, evita el problema.</li></ol><h2 id="los-resultados-de-busqueda-parecen-desactualizados" tabindex="-1">Los resultados de búsqueda parecen desactualizados <a class="header-anchor" href="#los-resultados-de-busqueda-parecen-desactualizados" aria-label="Permalink to &quot;Los resultados de búsqueda parecen desactualizados&quot;">​</a></h2><p>Las unidades NTFS y ReFS se actualizan desde el USN Journal casi en tiempo real; otros sistemas de archivos locales (FAT32, exFAT, ...) se vigilan directamente en busca de cambios, con la misma continuidad. Si algo sigue pareciendo desactualizado (un archivo que acabas de crear no aparece, o un archivo eliminado sigue apareciendo), usa <strong>Reconstruir índice</strong> en la unidad afectada, en <strong>Configuración → Índice → Unidades locales</strong> (o <strong>Unidades de red</strong>).</p><h2 id="una-unidad-de-red-nunca-parece-actualizarse" tabindex="-1">Una unidad de red nunca parece actualizarse <a class="header-anchor" href="#una-unidad-de-red-nunca-parece-actualizarse" aria-label="Permalink to &quot;Una unidad de red nunca parece actualizarse&quot;">​</a></h2><p>Los recursos de red no tienen un USN Journal que Lertaro pueda vigilar, así que se vuelven a escanear según una programación en su lugar. Comprueba el <strong>Modo de actualización</strong> de la unidad en <strong>Configuración → Índice → Unidades de red</strong> — si está configurado en <strong>Manual</strong>, nada se actualiza automáticamente; cámbialo a un intervalo programado, o usa <strong>Reconstruir índice</strong> para actualizar bajo demanda. Para recursos compartidos SMB en NAS con enlaces simbólicos especiales o bucles de carpetas recursivos, el motor de escaneo incluye detección de bucles integrada para evitar duplicados.</p><h2 id="la-ventana-de-vista-previa-se-ve-mal-recortada" tabindex="-1">La ventana de vista previa se ve mal / recortada <a class="header-anchor" href="#la-ventana-de-vista-previa-se-ve-mal-recortada" aria-label="Permalink to &quot;La ventana de vista previa se ve mal / recortada&quot;">​</a></h2><p>Esto no debería ocurrir — Lertaro ajusta automáticamente la posición y el tamaño de la ventana de vista previa QuickLook al área utilizable de tu monitor. Si sigues viendo el contenido recortado, prueba <strong>Configuración → General → Vista previa → Restablecer ajustes de la ventana de vista previa</strong> para descartar un valor manual de ancho/alto poco habitual, y asegúrate de tener la última versión.</p><h2 id="un-archivo-carpeta-no-aparece-en-absoluto" tabindex="-1">Un archivo/carpeta no aparece en absoluto <a class="header-anchor" href="#un-archivo-carpeta-no-aparece-en-absoluto" aria-label="Permalink to &quot;Un archivo/carpeta no aparece en absoluto&quot;">​</a></h2><ul><li>Comprueba que no esté excluido — <strong>Configuración → Índice → Reglas de exclusión</strong> admite rutas exactas, patrones glob y expresiones regulares, y cualquiera de los tres podría estar afectándolo sin querer.</li><li>Comprueba que la unidad en la que se encuentra esté habilitada en <strong>Configuración → Índice → Unidades locales/de red</strong>.</li></ul><h2 id="escribir-en-chino-u-otro-idioma-con-ime-en-la-ventana-en-linea-no-funciona" tabindex="-1">Escribir en chino (u otro idioma con IME) en la ventana en línea no funciona <a class="header-anchor" href="#escribir-en-chino-u-otro-idioma-con-ime-en-la-ventana-en-linea-no-funciona" aria-label="Permalink to &quot;Escribir en chino (u otro idioma con IME) en la ventana en línea no funciona&quot;">​</a></h2><p>La <a href="./getting-started.html#las-tres-ventanas">ventana en línea</a> deliberadamente nunca le quita el foco real de teclado a la ventana en la que está acoplada — eso es lo que te permite cerrarla y aterrizar exactamente donde estabas, sin parpadeo de foco. Sin embargo, la composición de un IME (la lista de candidatos, y el carácter que realmente confirma) solo ocurre para la ventana que tenga el foco <em>real</em>, que siempre es la aplicación acoplada, nunca Lertaro — así que no hay ningún mensaje que Lertaro pueda interceptar para capturar lo que escribiste. Esto es una limitación estructural de cómo funciona la ventana en línea, no un error.</p><p>Dos opciones:</p><ul><li>Escribe directamente la romanización en pinyin (sin necesidad de la ventana emergente de candidatos del IME) — Lertaro compara automáticamente los nombres de archivo en chino por pinyin, ver <a href="./search-syntax.html#nombres-de-archivo-en-chino-alias-en-pinyin">Sintaxis de búsqueda</a>.</li><li>Usa en su lugar la <a href="./getting-started.html#las-tres-ventanas">ventana rápida</a> (doble pulsación de <code>Ctrl</code> por defecto) — es una ventana con foco real, así que la composición del IME funciona ahí con normalidad.</li></ul><h2 id="¿sigues-atascado" tabindex="-1">¿Sigues atascado? <a class="header-anchor" href="#¿sigues-atascado" aria-label="Permalink to &quot;¿Sigues atascado?&quot;">​</a></h2><p>Comprueba las pestañas de registro <strong>App</strong>, <strong>Hook</strong> y <strong>Service</strong> en <strong><a href="./settings/service-status.html">Configuración → Estado del Servicio</a></strong> — el cuadro de búsqueda ahí filtra por palabra clave, y el desplegable de nivel filtra por gravedad — antes de reportar un problema en GitHub.</p>',17)])])}const g=e(i,[["render",s]]);export{m as __pageData,g as default};
